## 1. Identification Strategy
- Method: Sharp Regression Discontinuity Design (RDD).
- Why: Loan approval switches discretely at a credit score threshold. Individuals infinitesimally below and above the cutoff are comparable in unobservables; the discontinuous jump in treatment (approval) isolates the local average treatment effect of meeting the minimum score on default rates.
- Key assumptions:
  - Continuity: Potential outcomes (default rates absent treatment) vary smoothly in credit score at the cutoff.
  - No precise manipulation: Applicants cannot sort precisely around the threshold to end up just above it.
  - Correct functional form locally: With a sufficiently small bandwidth, a local linear (and checked with quadratic) specification approximates the conditional expectation on each side.

## 2. R Code
```r
# Complete, self-contained R code that:
# - Reads the CSV file from the path provided
# - Runs the appropriate causal analysis
# - Prints a clear numerical result (coefficient, CAR, etc.)
# - Includes basic robustness checks

# Load packages (use if available; otherwise fall back to base R)
use_pkg <- function(p) {
  if (!requireNamespace(p, quietly = TRUE)) return(FALSE)
  suppressPackageStartupMessages(library(p, character.only = TRUE))
  TRUE
}
have_sandwich <- use_pkg("sandwich")
have_lmtest   <- use_pkg("lmtest")
have_rdrobust <- use_pkg("rdrobust")
have_rddensity <- use_pkg("rddensity")

# 1) Read data
path <- "experiments/exp_b/data/s89_data.csv"
dat <- read.csv(path)
stopifnot(all(c("running_var","treated","y") %in% names(dat)))
# Clean/confirm types
dat$running_var <- as.numeric(dat$running_var)
dat$treated     <- as.integer(dat$treated)
dat$y           <- as.numeric(dat$y)
if ("near_cutoff" %in% names(dat)) dat$near_cutoff <- as.integer(dat$near_cutoff)

# 2) Infer/confirm cutoff
# Try to estimate the cutoff c that best matches treated = 1{running_var >= c}
rng <- range(dat$running_var, na.rm = TRUE)
grid <- seq(quantile(dat$running_var, 0.05, na.rm=TRUE),
            quantile(dat$running_var, 0.95, na.rm=TRUE), length.out = 200)
mism <- sapply(grid, function(cut) sum(abs(dat$treated - as.integer(dat$running_var >= cut))))
c_hat <- grid[which.min(mism)]
# If running_var looks scaled to [0,1], prefer 0.5 if it ties or is nearly as good
if (rng[1] >= -1e-8 && rng[2] <= 1+1e-8) {
  mis05 <- sum(abs(dat$treated - as.integer(dat$running_var >= 0.5)))
  if (mis05 <= min(mism) + 0) c_hat <- 0.5
}
cutoff <- as.numeric(c_hat)

cat(sprintf("Detected cutoff (credit score threshold): %.4f\n", cutoff))

# 3) Helper: local polynomial RD with triangular kernel and robust SE
fit_rd <- function(df, cutoff, h, poly = 1, donut = 0, min_per_side = 30) {
  x <- df$running_var - cutoff
  keep <- abs(x) <= h & !is.na(df$y) & !is.na(df$treated) & !is.na(x)
  if (donut > 0) keep <- keep & (abs(x) > donut)
  d <- df[keep, , drop = FALSE]
  x <- d$running_var - cutoff
  # Ensure min per side; if not, return NA
  n_left  <- sum(x < 0)
  n_right <- sum(x >= 0)
  if (n_left < min_per_side || n_right < min_per_side) {
    return(list(ok=FALSE, msg="Insufficient observations per side within h/donut.",
                h=h, donut=donut, n_left=n_left, n_right=n_right))
  }
  # Triangular kernel weights
  w <- pmax(0, 1 - abs(x) / h)
  # Construct formula: y ~ treat + x + treat:x + [x^2 + treat:x^2 if poly=2]
  treat <- as.integer(d$running_var >= cutoff)
  df_fit <- data.frame(y = d$y, treat = treat, x = x, w = w)
  if (poly == 1) {
    form <- y ~ treat + x + treat:x
  } else if (poly == 2) {
    df_fit$x2 <- x^2
    form <- y ~ treat + x + treat:x + x2 + treat:x2
  } else {
    stop("Only poly=1 or 2 supported.")
  }
  m <- lm(form, data = df_fit, weights = w)
  # Robust SE if available
  if (have_sandwich && have_lmtest) {
    vc <- sandwich::vcovHC(m, type = "HC1")
    coefs <- lmtest::coeftest(m, vcov. = vc)
    se <- sqrt(diag(vc))["treat"]
    est <- coef(m)["treat"]
    tval <- est / se
    pval <- 2 * pt(abs(tval), df = nobs(m) - length(coef(m)), lower.tail = FALSE)
  } else {
    s <- summary(m)
    est <- coef(m)["treat"]
    se  <- s$coefficients["treat","Std. Error"]
    pval <- s$coefficients["treat","Pr(>|t|)"]
  }
  ci_low <- est - 1.96 * se
  ci_high <- est + 1.96 * se
  list(ok=TRUE, est=as.numeric(est), se=as.numeric(se), ci=c(ci_low, ci_high), p=pval,
       h=h, donut=donut, poly=poly, n_left=n_left, n_right=n_right, n=n_left+n_right)
}

# 4) Choose a default bandwidth with a simple rule, then ensure enough obs per side
range_x <- diff(range(dat$running_var, na.rm = TRUE))
h0 <- 0.15 * range_x
# Increase h until min 30 per side or until it hits half the range
ensure_h <- function(df, cutoff, h_start, poly=1, donut=0) {
  h <- h_start
  for (iter in 1:10) {
    res <- fit_rd(df, cutoff, h, poly=poly, donut=donut)
    if (res$ok) return(list(h=h, res=res))
    h <- h * 1.3
    if (h >= 0.5 * range_x) break
  }
  # Final try with large h
  res <- fit_rd(df, cutoff, min(0.5*range_x, max(1e-6, h)), poly=poly, donut=donut)
  list(h=min(0.5*range_x, max(1e-6, h)), res=res)
}
main_try <- ensure_h(dat, cutoff, h0, poly=1, donut=0)
main_res <- main_try$res
if (!isTRUE(main_res$ok)) {
  stop("Could not fit main RD: ", main_res$msg)
}

cat("\nMain RD estimate (local linear, triangular kernel):\n")
cat(sprintf("  Tau = %.4f, SE = %.4f, 95%% CI = [%.4f, %.4f], p = %.4g\n",
            main_res$est, main_res$se, main_res$ci[1], main_res$ci[2], main_res$p))
cat(sprintf("  Bandwidth h = %.4f, N_left = %d, N_right = %d\n",
            main_res$h, main_res$n_left, main_res$n_right))

# 5) rdrobust version (if available)
if (have_rdrobust) {
  suppressWarnings({
    rd_fit <- try(rdrobust::rdrobust(y = dat$y, x = dat$running_var, c = cutoff, kernel = "triangular"), silent = TRUE)
  })
  if (!inherits(rd_fit, "try-error")) {
    # Use robust bias-corrected estimate (tau_bc) and its SE
    tau_bc <- as.numeric(rd_fit$Estimate[1, "tau.bc"])
    se_bc  <- as.numeric(rd_fit$Estimate[1, "se.rb"])
    ci_lo  <- tau_bc - 1.96 * se_bc
    ci_hi  <- tau_bc + 1.96 * se_bc
    p_bc   <- 2 * (1 - pnorm(abs(tau_bc / se_bc)))
    cat("\nrdrobust (bias-corrected) estimate:\n")
    cat(sprintf("  Tau_bc = %.4f, SE_rb = %.4f, 95%% CI = [%.4f, %.4f], p = %.4g\n",
                tau_bc, se_bc, ci_lo, ci_hi, p_bc))
    if (!is.null(rd_fit$h)) {
      cat(sprintf("  rdrobust bandwidths (h_left, h_right) = (%.4f, %.4f)\n",
                  rd_fit$h[1], rd_fit$h[2]))
    }
  }
}

# 6) Robustness checks

# (a) Different bandwidths
cat("\nRobustness: Bandwidth sensitivity (local linear):\n")
for (mult in c(0.75, 1.00, 1.50, 2.00)) {
  h_try <- max(1e-6, main_res$h * mult)
  r <- fit_rd(dat, cutoff, h_try, poly=1, donut=0)
  if (r$ok) {
    cat(sprintf("  h = %.4f -> Tau = %.4f (SE = %.4f), 95%% CI [%.4f, %.4f], p = %.4g, N_L=%d, N_R=%d\n",
                h_try, r$est, r$se, r$ci[1], r$ci[2], r$p, r$n_left, r$n_right))
  } else {
    cat(sprintf("  h = %.4f -> insufficient data per side\n", h_try))
  }
}

# (b) Quadratic polynomial within main bandwidth
quad_res <- fit_rd(dat, cutoff, main_res$h, poly=2, donut=0)
cat("\nRobustness: Quadratic local polynomial:\n")
if (quad_res$ok) {
  cat(sprintf("  Tau (poly=2) = %.4f (SE = %.4f), 95%% CI [%.4f, %.4f], p = %.4g\n",
              quad_res$est, quad_res$se, quad_res$ci[1], quad_res$ci[2], quad_res$p))
} else {
  cat("  Could not estimate quadratic model (insufficient data per side)\n")
}

# (c) Donut RDD: drop a small window around the cutoff
donut_w <- 0.02 * range_x
donut_res <- fit_rd(dat, cutoff, main_res$h, poly=1, donut=donut_w)
cat("\nRobustness: Donut RDD (exclude |score - cutoff| <= small window):\n")
if (donut_res$ok) {
  cat(sprintf("  Donut width = %.4f -> Tau = %.4f (SE = %.4f), 95%% CI [%.4f, %.4f], p = %.4g, N_L=%d, N_R=%d\n",
              donut_w, donut_res$est, donut_res$se, donut_res$ci[1], donut_res$ci[2],
              donut_res$p, donut_res$n_left, donut_res$n_right))
} else {
  cat("  Donut RDD could not be estimated (insufficient data per side)\n")
}

# (d) Restrict to observations flagged near the cutoff (if available)
if ("near_cutoff" %in% names(dat)) {
  dat_near <- subset(dat, near_cutoff == 1)
  near_try <- ensure_h(dat_near, cutoff, h0, poly=1, donut=0)
  near_res <- near_try$res
  cat("\nRobustness: Subsample flagged near_cutoff == 1:\n")
  if (isTRUE(near_res$ok)) {
    cat(sprintf("  Tau_near = %.4f (SE = %.4f), 95%% CI [%.4f, %.4f], p = %.4g; h = %.4f, N_L=%d, N_R=%d\n",
                near_res$est, near_res$se, near_res$ci[1], near_res$ci[2],
                near_res$p, near_res$h, near_res$n_left, near_res$n_right))
  } else {
    cat("  Could not estimate on near_cutoff subsample (insufficient data per side)\n")
  }
}

# 7) Optional: Density/manipulation check at cutoff
if (have_rddensity) {
  cat("\nMcCrary density test (rddensity) at cutoff:\n")
  dens <- try(rddensity::rddensity(X = dat$running_var, c = cutoff), silent = TRUE)
  if (!inherits(dens, "try-error")) {
    tst <- rddensity::rddensity.test(dens)
    cat(sprintf("  Log density diff = %.4f, p-value = %.4g\n", tst$test$coef[1], tst$test$p[1]))
  } else {
    cat("  rddensity failed to run.\n")
  }
} else {
  cat("\nNote: rddensity not available; skipping formal manipulation test.\n")
}
```

## 3. Expected Findings
- Sign: Positive. Being just above the approval threshold likely increases default rates because it expands credit to marginal (riskier) borrowers who would otherwise be denied.
- Magnitude: Around 5–15 percentage points increase in default probability at the cutoff, based on typical credit scoring RD evidence and the previewed rows where above-threshold observations show higher default rates. The exact estimate will depend on the local bandwidth but should be robustly positive.
